export const orderedMessageKeys: string[] = [];
for (const encoded of compressedMessageKeys) {
  const shared = encoded.charCodeAt(0) - 35;
  const previous = orderedMessageKeys[orderedMessageKeys.length - 1] ?? "";
  orderedMessageKeys.push(previous.slice(0, shared) + encoded.slice(1));
}

